import "core-js/modules/es6.function.name";
import "core-js/modules/web.dom.iterable";
// import TsTable from '@/resources/components/TsTable/TsTable';//这里需要保留，为了注入样式
// import TsFormInput from '@/resources/plugins/TsForm/TsFormInput';
// import TsFormSelect from '@/resources/plugins/TsForm/TsFormSelect';

export default {
  name: '',
  components: {
    // TsFormInput,
    // TsFormSelect,
    // TsTable
  },
  props: {
    attrData: {
      type: Object
    },
    valueList: {
      type: Array
    }
  },
  data: function data() {
    return {
      dataList: [{}]
    };
  },
  beforeCreate: function beforeCreate() {},
  created: function created() {},
  beforeMount: function beforeMount() {},
  mounted: function mounted() {},
  beforeUpdate: function beforeUpdate() {},
  updated: function updated() {},
  activated: function activated() {},
  deactivated: function deactivated() {},
  beforeDestroy: function beforeDestroy() {},
  destroyed: function destroyed() {},
  methods: {
    formatDataList: function formatDataList(dataList) {
      var finalList = [];
      if (dataList && dataList.length > 0) {
        dataList.forEach(function (element) {
          finalList.push({
            value: element,
            text: element
          });
        });
      }
      return finalList;
    },
    addData: function addData() {
      this.dataList.push({});
    },
    removeData: function removeData(d) {
      var index = null;
      for (var i = 0; i < this.dataList.length; i++) {
        if (this.dataList[i] == d) {
          index = i;
          break;
        }
      }
      this.dataList.splice(index, 1);
    },
    valid: function valid() {
      //验证数据合法性
      return true;
    }
  },
  filter: {},
  computed: {
    tableData: function tableData() {
      var theadList = [];
      if (this.attrData && this.attrData.config && this.attrData.config.dataList) {
        var width = 100 / this.attrData.config.dataList.length + '%';
        this.attrData.config.dataList.forEach(function (element) {
          theadList.push({
            key: element.name,
            title: element.label,
            type: element.type,
            dataList: element.dataList,
            width: width
          });
        });
        theadList.push({
          key: '_action'
        });
      }
      return {
        theadList: theadList,
        tbodyList: this.dataList
      };
    },
    headerList: function headerList() {
      if (this.attrData && this.attrData.config && this.attrData.config.dataList) {
        return this.attrData.config.dataList;
      } else {
        return [];
      }
    }
  },
  watch: {
    valueList: {
      handler: function handler(v) {
        if (v && v.length > 0) {
          if (typeof v[0] == 'string') {
            //从数据库出来的值是字符串，需要还原为数组
            this.dataList = JSON.parse(v[0]);
          } else {
            //ciEntityQueue里的暂存数据是数组，不需要转换
            this.dataList = v[0];
          }
        }
      },
      deep: true,
      immediate: true
    },
    dataList: {
      handler: function handler(v) {
        this.$emit('setData', [v]);
        this.$emit('setValue', [v]);
      },
      deep: true
    }
  }
};
